const double loading_area[2] = {250, 250};

// Recources (Layout 2)
const double raw_materials[2]           = {6550.0, 3250.0};
const double texturized_materials[2]    = {6200.0, 100.0};
const double diffused_materials[2]      = {5500.0, 100.0};
